import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { convertRpHandler } from "../handlers/convertRpHandler";
import type { ApiError } from "../runtime/client";
import type { ConvertRpRequest } from "../types/ConvertRpRequest";

type Data = Awaited<ReturnType<typeof convertRpHandler>>;
type Vars = ConvertRpRequest;

export function useConvertRp(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => convertRpHandler(vars),
    ...options,
  });
}
